// Ambil semua item dari node sebelumnya
const allItems = $input.all();
const rows = allItems.map(item => item.json);

// Filter: hanya Status_Workflow = 'pending' atau 'reported'
const activeRows = rows.filter(r =>
  r.Status_Workflow === 'pending' || r.Status_Workflow === 'reported'
);

if (activeRows.length === 0) {
  return [{
    json: {
      hasItems: false,
      waMessage: '',
      rowsToUpdateNotify: [],
      rowsToUpdateStatus: [],
      rowsToUpdateFinalize: []
    }
  }];
}

// ── Group by Nama_Project ──────────────────────────────────────
const projects = {};
activeRows.forEach(row => {
  const proj = row.Nama_Project || 'Tidak Diketahui';
  if (!projects[proj]) projects[proj] = [];
  projects[proj].push(row);
});

// ── Format tanggal hari ini ─────────────────────────────────────
const now = new Date();
const formattedDate = now.toLocaleDateString('id-ID', {
  day: '2-digit', month: '2-digit', year: '2-digit'
});

// ── Build pesan WhatsApp ────────────────────────────────────────
let msg = `📋 *To Do List (${formattedDate})*\n\n`;

const projectNames = Object.keys(projects);
projectNames.forEach((proj, idx) => {
  msg += `${idx+1}. *${proj}*\n`;

  projects[proj].forEach(item => {
    const pendingMark = item.Status_Workflow === 'pending' ? ' 🆕' : '';
    const statusPekerjaanLower = (item.Status_Pekerjaan || '').toLowerCase();
    let pekerjaanMark = '';
    if (statusPekerjaanLower === 'selesai') pekerjaanMark = ' ✅';
    if (statusPekerjaanLower === 'reject') pekerjaanMark = ' 🗑️';
    const highMark = item.Prioritas === 'Tinggi' ? ' 🔴' : '';
    msg += `• ${item.Komplain}${pendingMark}${pekerjaanMark}${highMark}\n`;
  });
  msg += '\n';
});

msg += `━━━━━━━━━━━━━━━\n`;
const total    = activeRows.length;
const reported = activeRows.filter(r => r.Status_Workflow === 'reported').length;
const pending  = activeRows.filter(r => r.Status_Workflow === 'pending').length;
msg += `📊 *Summary:* Total ${total} | ⏳ Pending: ${pending} | 📌 Reported: ${reported}\n\n`;
msg += `_Dikirim otomatis setiap hari_`;

// ── 1. Update Notify_Count untuk semua activeRows ───────────────
const rowsToUpdateNotify = activeRows.map(r => ({
  row_number: r.row_number,
  Notify_Count: (r.Notify_Count || 0) + 1
}));

// ── 2. Update Status_Workflow: pending → reported ───────────────
//    (setelah WA dikirim, komplain yang masih pending dianggap sudah dilaporkan)
const rowsToUpdateStatus = activeRows
  .filter(r => r.Status_Workflow === 'pending')
  .map(r => ({
    row_number: r.row_number,
    Status: 'reported'          // field 'Status' akan dipakai di node update sheet
  }));

// ── 3. Finalize untuk item yang selesai/reject dan belum di-resolve ──
const rowsToUpdateFinalize = activeRows
  .filter(r => {
    const statusLower = (r.Status_Pekerjaan || '').toLowerCase();
    return (statusLower === 'selesai' || statusLower === 'reject') && (r.Status_Pekerjaan_Counter || 0) === 0;
  })
  .map(r => ({
    row_number: r.row_number,
    Status_Workflow: 'resolved',
    Status_Pekerjaan_Counter: 1
  }));

return [{
  json: {
    hasItems: true,
    waMessage: msg,
    rowsToUpdateNotify: rowsToUpdateNotify,
    rowsToUpdateStatus: rowsToUpdateStatus,     // ← baru
    rowsToUpdateFinalize: rowsToUpdateFinalize,
    summary: { total, pending, reported }
  }
}];

// Tidak ada komplain aktif hari ini - workflow berhenti di sini
console.log('[Tim Interior] Tidak ada komplain pending/resolved hari ini. Tidak ada WA yang dikirim.');
return [{ json: { skipped: true, reason: 'Tidak ada komplain aktif' } }];

const formatNode = $node["Format Pesan Rekapan"];
const rows = formatNode.json.rowsToUpdateNotify || [];
if (rows.length === 0) return [];
return rows.map(row => ({ json: row }));

